Tool response:
Tool: record_payment
Description: Record Payment
Parameters:
    {
      "type": "object",
      "properties": {
        "invoice_id": {
          "type": "integer",
          "title": "Invoice Id",
          "description": ""
        },
        "amount": {
          "type": "number",
          "exclusiveMinimum": 0.0,
          "title": "Amount",
          "description": "The payment amount"
        },
        "payment_method": {
          "type": "string",
          "title": "Payment Method",
          "description": "The method of payment (cash, check, credit_card, debit_card, insurance, other)"
        },
        "payment_date": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Payment Date",
          "description": "The date of payment (defaults to current date if not provided)"
        },
        "reference_number": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Reference Number",
          "description": "Reference number for the payment"
        },
        "notes": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Notes",
          "description": "Additional notes about the payment"
        }
      },
      "required": [
        "invoice_id",
        "amount",
        "payment_method"
      ]
    }

